public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int[][] a = new int[3][3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                a[i][j] = fs.nextInt();
            }
        }

        int n = fs.nextInt();
        boolean[][] marked = new boolean[3][3];

        for (int k = 0; k < n; k++) {
            int b = fs.nextInt();
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (a[i][j] == b) {
                        marked[i][j] = true;
                    }
                }
            }
        }

        boolean bingo = false;

        for (int i = 0; i < 3; i++) {
            if (marked[i][0] && marked[i][1] && marked[i][2]) bingo = true;
            if (marked[0][i] && marked[1][i] && marked[2][i]) bingo = true;
        }

        if (marked[0][0] && marked[1][1] && marked[2][2]) bingo = true;
        if (marked[0][2] && marked[1][1] && marked[2][0]) bingo = true;

        System.out.println(bingo ? "Yes" : "No");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

